const item = $input.item.json;
const rec = item.record || {};
const name = item.product_name || 'Produto';
const minPrice = (rec.min_price || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const avgPrice = (rec.avg_price || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const maxPrice = (rec.max_price || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const bestStore = rec.best_store || 'Loja Online';
const delta = (rec.delta_pct || 0);

let deltaStr = '➡️ Estável (0%)';
if (delta < 0) {
  deltaStr = `📉 ${delta.toFixed(1)}% (Caiu vs ontem!)`;
} else if (delta > 0) {
  deltaStr = `📈 +${delta.toFixed(1)}% (Subiu vs ontem)`;
}

let badge = '🟡 Preço Regular';
if (rec.recommendation === 'EXCELLENT') {
  badge = '🟢 <b>EXCELENTE MOMENTO DE COMPRA!</b>';
} else if (rec.recommendation === 'HIGH') {
  badge = '🔴 <b>PREÇO ALTO — RECOMENDAMOS AGUARDAR</b>';
}

const reason = rec.recommendation_reason || '';
const url = rec.best_url || '';

const message = `📊 <b>RELATÓRIO DIÁRIO DE PREÇO</b>\n\n📦 <b>${name}</b>\n\n💰 <b>Menor Preço:</b> ${minPrice}\n🏪 <b>Loja Mais Barata:</b> <b>${bestStore}</b>\n📊 <b>Média de Mercado:</b> ${avgPrice}\n📈 <b>Maior Preço:</b> ${maxPrice}\n🔄 <b>Variação:</b> ${deltaStr}\n\n💡 <b>Veredito:</b>\n${badge}\n<i>${reason}</i>\n\n🔗 <a href="${url}">Ver Oferta no Buscapé / Loja</a>`;

return {
  product_id: item.product_id,
  product_name: name,
  recommendation: rec.recommendation,
  min_price: rec.min_price,
  best_url: url,
  telegram_message: message
};
